//! Port of python/tests/test_rl_phase_83.py (TestLowBudgetComparison).

use std::collections::HashSet;

use reasoning_evaluation::run_low_budget_comparison;

#[test]
fn test_low_budget_comparison_runs_end_to_end_with_tiny_params() {
    // Not the real published experiment (too slow for a unit test) — just
    // confirms the wiring runs to completion and returns well-formed data.
    // The real numbers are in RL_TRAINING.md and the module docstring,
    // generated by an actual run.
    let report = run_low_budget_comparison(15, 1, 3, 6, 30, 30, 0).unwrap();
    assert_eq!(report.conditions.len(), 4);
    let names: HashSet<&str> = report.conditions.iter().map(|c| c.name.as_str()).collect();
    let expected: HashSet<&str> = [
        "uniform",
        "prm_guided",
        "grpo_raw_sampling",
        "grpo_mcts_sourced",
    ]
    .into_iter()
    .collect();
    assert_eq!(names, expected);
    for c in &report.conditions {
        assert!((0.0..=1.0).contains(&c.solve_rate));
        assert!(c.ci_lo <= c.solve_rate);
        assert!(c.ci_hi >= c.solve_rate);
    }
}
